# Generated by build.py from recipe.yml for recipe tftp-move-a-firmware-fetch-to-http. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/readme.txt'), "firmware images`n")
cmd /c 'head -c 1300 /dev/urandom > site/firmware.bin'
cmd /c 'head -c 1024 /dev/urandom > site/exact.bin'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'tftp://127.0.0.1:8080/', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o over-tftp.bin tftp://127.0.0.1:8080/firmware.bin -o over-http.bin http://127.0.0.1:8080/firmware.bin && cmp over-tftp.bin over-http.bin && echo identical } finally { Stop-Process $server0 }
